initial_condition:
with {
    the SUT in the "initial state"
}

test_cases.then:
then {
    the SUT sends a valid Response containing:
        Response Body containing an Entity Type Info and
        Response Status Code set to 200
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/types/{type}'
        method set to 'GET'
        Retrieve Entity Type, with type set to 'Building', with Header['Link'] containing 'https://forge.etsi.org/rep/cim/ngsi-ld-test-suite/-/raw/develop/resources/jsonld-contexts/ngsi-ld-test-suite-compound.jsonld'
}
